# The HTML report's stylesheet, without its faces (saved_faces.py).
EXPORT_STYLE = (
    "\n"
    ":root { color-scheme: light; --ink:#242733; --dim:#596174; --rule:#C8BEA8; --head:#EFE8D8; --bg:#F7F3E8; --band:#FFFDF6; }\n"
    "* { box-sizing: border-box; }\n"
    "body { margin:0; padding:2rem 1.25rem 4rem; background:var(--bg); color:var(--ink);\n"
    "       font:16px/1.55 \"TAE Symbols\",\"TAE Symbols Sun\",\"EB Garamond\",\"DejaVu Sans\",serif; }\n"
    "main { max-width: 62rem; margin: 0 auto; }\n"
    "h1 { font-size:1.7rem; font-weight:600; margin:0 0 .25rem; }\n"
    "h2 { font-size:1.15rem; font-weight:600; margin:2.2rem 0 .6rem; padding-bottom:.25rem;\n"
    "     border-bottom:2px solid var(--rule); }\n"
    "h3 { font-size:1rem; font-weight:600; margin:1.4rem 0 .4rem; }\n"
    "p.sub { color:var(--dim); margin:.1rem 0 1.4rem; font-size:.9rem; font-family:\"TAE Symbols\",\"TAE Symbols Sun\",\"Zij Interface\",\"Zij Interface Marks\",\"DejaVu Sans\",sans-serif; }\n"
    "p.scope { background:var(--band); border-left:3px solid var(--rule); margin:0 0 1.6rem;\n"
    "          padding:.7rem .9rem; font-size:.88rem; color:var(--dim); }\n"
    "p.cite { color:var(--dim); margin:.2rem 0 .5rem; font-size:.85rem; font-family:\"TAE Symbols\",\"TAE Symbols Sun\",\"Zij Interface\",\"Zij Interface Marks\",\"DejaVu Sans\",sans-serif; }\n"
    "p.label { font-weight:600; margin:.6rem 0 .3rem; font-size:.92rem; }\n"
    "p.none { color:var(--dim); margin:.2rem 0 1rem; }\n"
    "details { margin:.5rem 0 1rem; }\n"
    "details > summary { cursor:pointer; font-weight:600; padding:.45rem .6rem;\n"
    "                    background:var(--band); border:1px solid var(--rule); border-radius:3px; }\n"
    "details[open] > summary { margin-bottom:.8rem; }\n"
    ".wrap { overflow-x:auto; margin:0 0 1.2rem; }\n"
    "table { border-collapse:collapse; font-size:.82rem; font-family:\"TAE Symbols\",\"TAE Symbols Sun\",\"Zij Interface\",\"Zij Interface Marks\",\"DejaVu Sans\",sans-serif; min-width:100%; }\n"
    "th, td { border:1px solid var(--rule); padding:.3rem .5rem; text-align:left;\n"
    "         vertical-align:top; }\n"
    "th { background:var(--head); color:var(--dim); font-weight:400; white-space:nowrap; }\n"
    "tbody tr:nth-child(even) { background:var(--band); }\n"
    "footer { margin-top:3rem; padding-top:1rem; border-top:1px solid var(--rule);\n"
    "         color:var(--dim); font-size:.82rem; font-family:\"TAE Symbols\",\"TAE Symbols Sun\",\"Zij Interface\",\"Zij Interface Marks\",\"DejaVu Sans\",sans-serif; }\n"
    "@media (prefers-color-scheme: dark) {\n"
    "  :root { color-scheme: dark; --ink:#EAE3D2; --dim:#8B91A6; --rule:#242E47; --head:#151B2B; --bg:#070A12; --band:#0D1220; }\n"
    "}\n"
    "@media print {\n"
    "  :root { color-scheme: light; --ink:#242733; --dim:#596174; --rule:#C8BEA8; --head:#EFE8D8; --bg:#FFFFFF; --band:#FFFFFF; }\n"
    "  body { padding:0; font-size:11pt; }\n"
    "  details { break-inside:avoid; }\n"
    "  details > summary { background:none; border:none; padding:0; }\n"
    "  details:not([open]) > *:not(summary) { display:revert; }\n"
    "  .wrap { overflow:visible; }\n"
    "  table { font-size:8pt; }\n"
    "}\n"
)
